INSERT OR IGNORE INTO products(slug,name,category_slug,description,price,compare_price,images,huid,purity,weight,stock,rating,review_count,badge,artisan,artisan_story,is_active) VALUES('floral-silver-ring','Floral Silver Ring','rings','A delicate hand-filed floral band in 925 sterling silver, finished with a mirror polish that catches candlelight like dew.',1299,1899,'["/assets/img/rings.webp"]','H284193','925 Sterling Silver','4.2 g',34,4.8,124,'NEW','Ramesh Prajapat · Jaipur','Ramesh ji has been filing floral motifs in Jaipur’s Johari Bazaar for 19 years — this rosette is cut entirely by hand with a graver his father left him.',1);
INSERT OR IGNORE INTO products(slug,name,category_slug,description,price,compare_price,images,huid,purity,weight,stock,rating,review_count,badge,artisan,artisan_story,is_active) VALUES('diamond-cut-silver-ring','Diamond-cut Silver Ring','rings','Precision diamond-cut facets across the band — a quiet fire that works from boardroom to baraat.',1599,2200,'["/assets/img/diamond-cut-ring.jpg"]','H391207','925 Sterling Silver','5.1 g',21,4.7,98,'SALE','Mahesh Soni · Jaipur','Mahesh ji cuts every facet under a jeweller’s loupe, not a machine — forty-two separate angled strikes per ring.',1);
INSERT OR IGNORE INTO products(slug,name,category_slug,description,price,compare_price,images,huid,purity,weight,stock,rating,review_count,badge,artisan,artisan_story,is_active) VALUES('triple-band-silver-ring','Triple Band Silver Ring','rings','Three hand-soldered bands, each polished separately then united — our most-reviewed ring for a reason.',1499,NULL,'["/assets/img/triple-band-ring.jpg"]','H175542','925 Sterling Silver','6.3 g',40,4.9,195,'TOP RATED','Ramesh Prajapat · Jaipur','The three bands are soldered in sequence over a charcoal block, quenched, and re-polished between every stage.',1);
INSERT OR IGNORE INTO products(slug,name,category_slug,description,price,compare_price,images,huid,purity,weight,stock,rating,review_count,badge,artisan,artisan_story,is_active) VALUES('filigree-drop-earrings','Filigree Drop Earrings','earrings','Micro-filigree teardrops, each wire rolled and curled by hand in the Nathdwara tradition.',2199,2999,'["/assets/img/earrings.webp"]','H402981','925 Sterling Silver','3.8 g',28,4.8,87,'STAFF PICK','Kamala Devi · Nathdwara','Kamala ji trained at the temple-town workshops of Nathdwara; each drop takes four days of wire work.',1);
INSERT OR IGNORE INTO products(slug,name,category_slug,description,price,compare_price,images,huid,purity,weight,stock,rating,review_count,badge,artisan,artisan_story,is_active) VALUES('pearl-silver-earrings','Pearl & Silver Earrings','earrings','Freshwater pearls cradled in hand-formed 925 silver cups — evening light, bottled.',1799,2400,'["/assets/img/pearl-earrings.jpg"]','H558310','925 Sterling Silver','4.4 g',25,4.6,76,'NEW','Kamala Devi · Nathdwara','Each pearl is hand-matched in size and overtone before being set in Kamala ji’s claw cups.',1);
INSERT OR IGNORE INTO products(slug,name,category_slug,description,price,compare_price,images,huid,purity,weight,stock,rating,review_count,badge,artisan,artisan_story,is_active) VALUES('layered-chain-necklace','Layered Chain Necklace','necklaces','Three lengths, one clasp — a cascading layered chain that needs no second thought when you dress.',2799,3800,'["/assets/img/layered-chain.jpg"]','H610274','925 Sterling Silver','8.9 g',18,4.7,55,'NEW','Imran Sheikh · Jaipur','Imran ji builds each chain link-by-link, then welds and re-links so layers fall exactly as intended.',1);
INSERT OR IGNORE INTO products(slug,name,category_slug,description,price,compare_price,images,huid,purity,weight,stock,rating,review_count,badge,artisan,artisan_story,is_active) VALUES('classic-silver-necklace','Classic Silver Necklace','necklaces','The everyday heirloom — a substantial herringbone weave with a hidden box clasp.',2099,2800,'["/assets/img/classic-necklace.jpg"]','H733915','925 Sterling Silver','12.5 g',31,4.8,142,'NEW','Imran Sheikh · Jaipur','Our best-loved everyday chain: herringbone-woven, hand-finished, and built to outlast trends.',1);
INSERT OR IGNORE INTO products(slug,name,category_slug,description,price,compare_price,images,huid,purity,weight,stock,rating,review_count,badge,artisan,artisan_story,is_active) VALUES('heart-pendant','Heart Pendant','pendants','A plump, hand-raised heart on a weekend-proof chain. The gift that always lands.',999,1499,'["/assets/img/heart-pendant.jpg"]','H120987','925 Sterling Silver','2.6 g',52,4.9,201,'HOT','Sita Rathore · Jodhpur','Sita ji raises each heart from a single silver disc — hammered, annealed, re-shaped until the curve is perfect.',1);
